// Nacht-Ampel für den eingestellten Ort (Standard Zürich, im Mod aus der Einstellung «Ort»):
// astronomische Dunkelheit (Sonne unter −18°), Mondbeleuchtung, Wolken von Open-Meteo, Seeing von 7Timer.

import type { StatusleisteNacht } from '../types'

export const LAT = 47.3769
export const LON = 8.5417
export function forecastUrl(lat = LAT, lon = LON): string {
  return `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&hourly=cloud_cover&timezone=auto&forecast_days=3`
}

// 7Timer «astro»: alle 3 Stunden Seeing 1 (unter 0,5″, sehr ruhig) bis 8 (über 2,5″, sehr unruhig), kostenlos
export function seeingUrl(lat = LAT, lon = LON): string {
  return `https://www.7timer.info/bin/api.pl?lon=${lon}&lat=${lat}&product=astro&output=json`
}

export type SeeingForecast = { init: string; dataseries: { timepoint: number; seeing: number }[] }

// 7Timer-Antwort prüfen: nur mit init (Text) und dataseries (Liste), sonst undefined — eine 200-Antwort in fremder Form darf nicht werfen
export function parseSeeing(text: string): SeeingForecast | undefined {
  try {
    const s = JSON.parse(text)
    return typeof s?.init === 'string' && Array.isArray(s.dataseries) ? (s as SeeingForecast) : undefined
  } catch {
    return undefined
  }
}

// Mittleres Seeing (1–8) über die dunkle Zeit; init = Startzeit UTC als JJJJMMTTHH
export function seeingDuring(f: SeeingForecast, start: number, end: number): number | undefined {
  const m = /^(\d{4})(\d{2})(\d{2})(\d{2})$/.exec(f.init)
  if (!m) return undefined
  const base = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]), Number(m[4]))
  const values = f.dataseries
    .filter(d => {
      const at = base + d.timepoint * 3600000
      return at + 3 * 3600000 > start && at < end && d.seeing >= 1 && d.seeing <= 8
    })
    .map(d => d.seeing)
  return values.length ? values.reduce((a, b) => a + b, 0) / values.length : undefined
}

// Elf Stufen von grün über gelb nach rot, Gelb genau in der Mitte (Stufe 5; Vorgabe 14.10.2026: mindestens zehn,
// ungerade Zahl)
export const STEPS = ['#00C853', '#34D03F', '#64DD17', '#9BE30C', '#CCE806', '#FFEA00', '#FFC400', '#FF9F00', '#FF7A00', '#FF4D00', '#D50000']
const LETZTE = STEPS.length - 1
const GELB = LETZTE / 2

export function seeingColor(seeing: number | undefined): string {
  if (seeing === undefined) return 'gray'
  const i = Math.round(((Math.min(8, Math.max(1, seeing)) - 1) / 7) * LETZTE)
  return STEPS[i]
}

// Himmels-Ampel für den Punkt vorne in der Astro-Zeile (Vorgabe 14.10.2026: grün nur, wenn sich Rausschauen lohnt).
// Aus allen Werten der Astro-Zeile (Vorgabe 14.10.2026, nicht nur Wolken und Seeing): Jeder Wert ergibt eine Stufe
// 0–10, die schlechteste bestimmt die Farbe, die übrigen schieben sie etwas weiter Richtung Rot (15 % ihrer Summe).
//   Wolken     0 % → 0, 100 % → 10: allein bis Rot, denn fürs blosse Auge zählen die Wolken zuerst
//   Seeing     1 → 0, 8 → 5: höchstens Gelb
//   Mond       Neumond 0, Vollmond 4: heller Himmel, aber kein Grund, drinnen zu bleiben
//   Taupunkt   Abstand Temperatur − Taupunkt ab 6 °C → 0, 1 °C und weniger → 7: Tau und Dunst
//   Feuchte    bis 75 % → 0, 100 % → 7
// Ohne Wolkenwert grau: dann lässt sich nichts sagen, auch wenn alles andere gut wäre. Temperatur, Taupunkt und Feuchte
// sind die aktuellen Werte (statusleiste: eigene Station, Cockpit: Open-Meteo am Ort), Wolken, Seeing und Mond gelten
// für die kommende dunkle Zeit.
export type HimmelWerte = { moon?: number; temp?: number; dewPoint?: number; hum?: number }
export const MOND_STUFE_MAX = 4
export function himmelStufe(cloud: number | undefined, seeing: number | undefined, w: HimmelWerte = {}): number | undefined {
  const zahl = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)
  const klemme = (v: number, max: number) => Math.min(max, Math.max(0, v))
  if (!zahl(cloud)) return undefined
  const stufen = [(klemme(cloud, 100) / 100) * LETZTE]
  if (zahl(seeing)) stufen.push(((Math.min(8, Math.max(1, seeing)) - 1) / 7) * GELB)
  if (zahl(w.moon)) stufen.push((klemme(w.moon, 100) / 100) * MOND_STUFE_MAX)
  if (zahl(w.temp) && zahl(w.dewPoint)) stufen.push(klemme(((6 - (w.temp - w.dewPoint)) / 5) * 7, 7))
  if (zahl(w.hum)) stufen.push(klemme(((w.hum - 75) / 25) * 7, 7))
  const schlechteste = Math.max(...stufen)
  const rest = stufen.reduce((a, b) => a + b, 0) - schlechteste
  return Math.min(LETZTE, Math.round(schlechteste + 0.15 * rest))
}
export function himmelFarbe(cloud: number | undefined, seeing: number | undefined, w: HimmelWerte = {}): string {
  const s = himmelStufe(cloud, seeing, w)
  return s === undefined ? 'gray' : (STEPS[s] ?? 'gray')
}

// Mondphase 0–1 (0 Neumond, 0,5 Vollmond) aus beleuchtetem Anteil und «zunehmend» (so steht es im State)
export function mondPhase(percent: number, isWaxing: boolean | undefined): number {
  const f = Math.min(1, Math.max(0, percent / 100))
  const p = Math.acos(1 - 2 * f) / (2 * Math.PI)
  return isWaxing === false ? 1 - p : p
}

// Mond als Bild (App): zwölf Stufen, 0 Neumond, 6 Vollmond (Vorgabe 14.10.2026: etwa 10–12 Stufen)
export const MOND_STUFEN = 12
export function mondStufe(phase: number): number {
  return Math.round((((phase % 1) + 1) % 1) * MOND_STUFEN) % MOND_STUFEN
}

// Mond als Zeichen (Konsole, kann keine Bilder): die acht Mond-Emoji. Auf der Südhalbkugel ist die Sichel gespiegelt.
export const MOND_EMOJI = ['🌑', '🌒', '🌓', '🌔', '🌕', '🌖', '🌗', '🌘'] as const
export function mondEmoji(phase: number, sued = false): string {
  const i = Math.round((((phase % 1) + 1) % 1) * 8) % 8
  return MOND_EMOJI[sued ? (8 - i) % 8 : i] ?? '🌑'
}

// Mond-Bild für die App: dunkle Scheibe, darauf der beleuchtete Teil der Stufe. Zunehmend ist rechts hell
// (Nordhalbkugel); abnehmend oder Südhalbkugel gespiegelt. Die Schattengrenze ist eine Halbellipse mit der Breite
// r·|cos(2π·Phase)|: bis zum Halbmond wölbt sie sich zur hellen Seite (Sichel), danach zur dunklen (dreiviertel).
export const MOND_GROESSE = 14
export function mondSvg(stufe: number, sued = false): string {
  const s = ((Math.round(stufe) % MOND_STUFEN) + MOND_STUFEN) % MOND_STUFEN
  const p = s / MOND_STUFEN
  const r = 6.5
  const kopf = `<svg xmlns="http://www.w3.org/2000/svg" width="${MOND_GROESSE}" height="${MOND_GROESSE}" viewBox="0 0 16 16">`
  const scheibe = `<circle cx="8" cy="8" r="${r}" fill="#2B3240" stroke="#6E7A8F" stroke-width="0.8"/>`
  const hell = '#ECE8D8'
  let licht = ''
  if (s === MOND_STUFEN / 2) licht = `<circle cx="8" cy="8" r="${r}" fill="${hell}"/>`
  else if (s !== 0) {
    // Teil auf der rechten Seite rechnen, für links spiegeln
    const q = p < 0.5 ? p : 1 - p
    const rx = Math.abs(Math.cos(2 * Math.PI * q)) * r
    const bogen = q < 0.25 ? 0 : 1
    const pfad = `M8 ${8 - r} A${r} ${r} 0 0 1 8 ${8 + r} A${rx.toFixed(3)} ${r} 0 0 ${bogen} 8 ${8 - r}Z`
    const links = p > 0.5 !== sued
    licht = `<path d="${pfad}" fill="${hell}"${links ? ' transform="matrix(-1 0 0 1 16 0)"' : ''}/>`
  }
  return `${kopf}${scheibe}${licht}</svg>`
}

const RAD = Math.PI / 180

function daysSinceJ2000(ms: number): number {
  return ms / 86400000 + 2440587.5 - 2451545.0
}

// Sonnenhöhe in Grad (vereinfachte Formel, auf etwa 0,5° genau — reicht für die Dämmerung)
export function sunAltitude(ms: number, lat = LAT, lon = LON): number {
  const d = daysSinceJ2000(ms)
  const g = (357.529 + 0.98560028 * d) * RAD
  const q = 280.459 + 0.98564736 * d
  const l = (q + 1.915 * Math.sin(g) + 0.02 * Math.sin(2 * g)) * RAD
  const e = (23.439 - 0.00000036 * d) * RAD
  const ra = Math.atan2(Math.cos(e) * Math.sin(l), Math.cos(l))
  const dec = Math.asin(Math.sin(e) * Math.sin(l))
  const gmst = (((18.697374558 + 24.06570982441908 * d) % 24) + 24) % 24
  const h = (gmst * 15 + lon) * RAD - ra
  return Math.asin(Math.sin(lat * RAD) * Math.sin(dec) + Math.cos(lat * RAD) * Math.cos(dec) * Math.cos(h)) / RAD
}

// Die astronomisch dunkle Zeit, die jetzt läuft oder als nächste kommt
export function darkness(now: number, lat = LAT, lon = LON): { start: number; end: number } | undefined {
  const step = 5 * 60000
  let start: number | undefined
  for (let t = now - 14 * 3600000; t <= now + 38 * 3600000; t += step) {
    const isDark = sunAltitude(t, lat, lon) < -18
    if (isDark && start === undefined) start = t
    if (!isDark && start !== undefined) {
      if (t > now) return { start, end: t }
      start = undefined
    }
  }
  return undefined
}

// Beleuchteter Anteil des Mondes in Prozent, dazu ob er zunimmt
export function moon(ms: number): { percent: number; isWaxing: boolean } {
  const jd = ms / 86400000 + 2440587.5
  const phase = ((((jd - 2451550.1) / 29.530588853) % 1) + 1) % 1
  return { percent: ((1 - Math.cos(2 * Math.PI * phase)) / 2) * 100, isWaxing: phase < 0.5 }
}

export type Forecast = { hourly: { time: string[]; cloud_cover: number[] }; utc_offset_seconds: number }

// Open-Meteo-Antwort prüfen: nur mit Stundenliste, Wolkenliste und endlichem Versatz, sonst undefined
export function parseForecast(text: string): Forecast | undefined {
  try {
    const f = JSON.parse(text)
    return Array.isArray(f?.hourly?.time) && Array.isArray(f.hourly.cloud_cover) && Number.isFinite(f.utc_offset_seconds) ? (f as Forecast) : undefined
  } catch {
    return undefined
  }
}

// Mittlere Bewölkung über die dunkle Zeit; nur endliche Werte (1e999 → Infinity würde im $.state zu null)
export function cloudsDuring(f: Forecast, start: number, end: number): number | undefined {
  const values: number[] = []
  f.hourly.time.forEach((t, i) => {
    const from = Date.parse(`${t}:00Z`) - f.utc_offset_seconds * 1000
    const cloud = f.hourly.cloud_cover[i]
    if (from + 3600000 > start && from < end && typeof cloud === 'number' && Number.isFinite(cloud)) values.push(cloud)
  })
  return values.length ? values.reduce((a, b) => a + b, 0) / values.length : undefined
}

// Ampel: unter 25 % Wolken gut, unter 60 % mässig, sonst bewölkt
export function level(cloud: number | undefined): StatusleisteNacht['level'] {
  if (cloud === undefined) return undefined
  return cloud < 25 ? 'gut' : cloud < 60 ? 'mässig' : 'bewölkt'
}

export function summarize(f: Forecast | undefined, now: number, s?: SeeingForecast, lat = LAT, lon = LON): StatusleisteNacht {
  const dark = darkness(now, lat, lon)
  if (!dark) return { level: 'keine' }
  const m = moon((dark.start + dark.end) / 2)
  const cloud = f ? cloudsDuring(f, dark.start, dark.end) : undefined
  return {
    start: dark.start,
    end: dark.end,
    offset: f?.utc_offset_seconds,
    moon: m.percent,
    isWaxing: m.isWaxing,
    cloud,
    level: level(cloud),
    seeing: s ? seeingDuring(s, dark.start, dark.end) : undefined,
  }
}

// Uhrzeit in Schweizer Zeit; Versatz aus der Vorhersage, sonst Winterzeit
export function clock(ms: number, offsetSeconds = 3600): string {
  const d = new Date(ms + offsetSeconds * 1000)
  return `${String(d.getUTCHours()).padStart(2, '0')}:${String(d.getUTCMinutes()).padStart(2, '0')}`
}

files.hooks/kosten.ts:
// API-Kosten im laufenden Abo-Monat über ALLE Claude-Code-Sitzungen (Konsole und Code-Tab der App), gerechnet aus
// den Verläufen in ~/.claude/projects (jede Antwort steht dort mit Modell und Token-Zahlen). Cowork und normale
// Chats auf claude.ai laufen in der Cloud und hinterlassen keine Token-Zahlen auf dem Rechner: nicht enthalten.
// Preise: Anthropic-Listenpreise in US-Dollar pro Million Tokens (Stand 25.09.2026, Skill claude-api).

export type Price = { input: number; output: number; write5m: number; write1h: number; read: number }

export const PRICES: Record<string, Price> = {
  'claude-opus-5-5': { input: 4, output: 20, write5m: 5, write1h: 8, read: 0.2 },
  'claude-opus-5': { input: 5, output: 25, write5m: 6.25, write1h: 10, read: 0.5 },
  'claude-sonnet-5-5': { input: 2, output: 10, write5m: 2.5, write1h: 4, read: 0.2 },
  'claude-sonnet-5': { input: 2, output: 10, write5m: 2.5, write1h: 4, read: 0.2 },
  'claude-fable-5-1': { input: 10, output: 50, write5m: 12.5, write1h: 20, read: 0.25 },
  'claude-fable-5': { input: 10, output: 50, write5m: 12.5, write1h: 20, read: 1 },
  'claude-haiku-4-5': { input: 1, output: 5, write5m: 1.25, write1h: 2, read: 0.1 },
}

// Websuche: 10 $ pro 1000 Abfragen
const WEB_SEARCH_USD = 0.01

export function priceFor(model: string): Price | undefined {
  // «claude-haiku-4-5-20251001» → «claude-haiku-4-5»
  return PRICES[model] ?? PRICES[model.replace(/-\d{8}$/, '')]
}

type Usage = {
  input_tokens?: number
  output_tokens?: number
  cache_read_input_tokens?: number
  cache_creation_input_tokens?: number
  cache_creation?: { ephemeral_5m_input_tokens?: number; ephemeral_1h_input_tokens?: number }
  server_tool_use?: { web_search_requests?: number }
  speed?: string
}

export function costOf(model: string, u: Usage): number | undefined {
  const p = priceFor(model)
  if (!p) return undefined
  const n = (v: number | undefined) => (typeof v === 'number' ? v : 0)
  const w1h = n(u.cache_creation?.ephemeral_1h_input_tokens)
  // ohne Aufteilung gilt die ganze Cache-Schreibmenge als 5-Minuten-Cache
  const w5m = u.cache_creation ? n(u.cache_creation.ephemeral_5m_input_tokens) : n(u.cache_creation_input_tokens)
  const tokens =
    n(u.input_tokens) * p.input +
    n(u.output_tokens) * p.output +
    w5m * p.write5m +
    w1h * p.write1h +
    n(u.cache_read_input_tokens) * p.read
  // Schnellmodus kostet das Doppelte
  const factor = u.speed === 'fast' ? 2 : 1
  return (tokens / 1e6) * factor + n(u.server_tool_use?.web_search_requests) * WEB_SEARCH_USD
}

// Kosten je Antwort einer Verlaufsdatei (JSONL), ab einem Zeitpunkt. Claude Code schreibt eine Antwort oft in
// mehreren Zeilen mit derselben message.id und derselben Abrechnung; wieder aufgenommene Sitzungen kopieren alte
// Antworten in eine neue Datei. Darum zählt jede message.id nur einmal (Schlüssel der Map).
export function costsInFile(jsonl: string, since: number): Map<string, number> {
  return new Map([...answersInFile(jsonl, since)].map(([id, a]) => [id, a.usd]))
}

// dasselbe mit dem Zeitpunkt jeder Antwort (fürs Kostenbuch); Modelle ohne Preis werden nicht gezählt, aber in
// ohnePreis gesammelt, damit die Anzeige darauf hinweisen kann
export function answersInFile(jsonl: string, since: number, ohnePreis?: Set<string>): Map<string, { t: number; usd: number }> {
  const out = new Map<string, { t: number; usd: number }>()
  for (const line of jsonl.split('\n')) {
    if (!line.includes('"usage"') || !line.includes('"assistant"')) continue
    try {
      const e = JSON.parse(line)
      const m = e.message
      if (e.type !== 'assistant' || !m?.usage || typeof m.model !== 'string' || m.model === '<synthetic>') continue
      const t = Date.parse(e.timestamp)
      if (!(t >= since)) continue
      const id = typeof m.id === 'string' ? m.id : `${e.requestId ?? ''}|${e.timestamp}`
      const usd = costOf(m.model, m.usage)
      if (usd !== undefined) out.set(id, { t, usd })
      else ohnePreis?.add(m.model)
    } catch {
      // unvollständige Zeile überspringen
    }
  }
  return out
}

// Kostenbuch: Die Desktop-App löscht mit einem Chat auch seinen Verlauf; ohne Buch fiele er aus der Monatssumme.
// Darum wird jede Antwort einmal mit Zeit, Betrag, Projektordner und Chat in ~/.claude/api-kostenbuch.json
// festgehalten und bleibt dort bis zum Ende des Abo-Monats, auch wenn der Verlauf verschwindet. Alle drei Werte
// (Chat / Projekt / alle) werden aus diesem Buch summiert, also aus denselben Antworten.
// Buchung: [Zeit ms, US-Dollar, Projektordner klein geschrieben, Chat-Kennung]
export type Buchung = [number, number, string, string]
export type Kostenbuch = { version: 1; since: number; antworten: Record<string, Buchung> }
export const KOSTENBUCH_DATEI = 'api-kostenbuch.json'

function istBuchung(b: unknown): b is Buchung {
  return (
    Array.isArray(b) && b.length === 4 && Number.isFinite(b[0]) && Number.isFinite(b[1]) &&
    typeof b[2] === 'string' && typeof b[3] === 'string'
  )
}

// Defekte Datei oder fremdes Format: leeres Ergebnis, nie ein Fehler; kaputte Einzeleinträge fallen weg
export function parseKostenbuch(text: string): Record<string, Buchung> {
  try {
    const j = JSON.parse(text)
    const out: Record<string, Buchung> = {}
    for (const [id, b] of Object.entries(j?.antworten ?? {})) if (istBuchung(b)) out[id] = b
    return out
  } catch {
    return {}
  }
}

// Vereinigung aller Quellen ab Monatsbeginn. Eine schon gebuchte Antwort behält Projekt und Chat der ersten
// Buchung (ein wieder aufgenommener Chat kopiert alte Antworten in eine neue Datei: nicht doppelt, nicht verschoben).
export function mergeKostenbuch(since: number, ...quellen: Iterable<[string, Buchung]>[]): Kostenbuch {
  const antworten: Record<string, Buchung> = {}
  for (const q of quellen) {
    for (const [id, b] of q) if (b[0] >= since && !(id in antworten)) antworten[id] = b
  }
  return { version: 1, since, antworten }
}

// Projektordner und Chat einer Verlaufsdatei unter ~/.claude/projects:
// <projekt>\<chat>.jsonl oder <projekt>\<chat>\subagents\agent-….jsonl (Unteragenten zählen zum Chat)
export function herkunft(path: string, projectsDir: string): { projekt: string; chat: string } {
  const rel = path.slice(projectsDir.length).replace(/^[\\/]+/, '').split(/[\\/]/)
  const projekt = (rel[0] ?? '').toLowerCase()
  const chat = rel.length > 2 ? rel[1] : (rel[1] ?? '').replace(/\.jsonl$/i, '')
  return { projekt, chat }
}

// chat bleibt undefined, solange das Buch keine Antwort dieses Chats kennt (dann zeigt die Leiste Claude Codes eigene Summe)
export function summen(buch: Kostenbuch, projekt: string, chat: string): { all: number; project: number; chat?: number; count: number } {
  const p = projekt.toLowerCase()
  let all = 0
  let project = 0
  let c: number | undefined
  let count = 0
  for (const [, usd, bp, bc] of Object.values(buch.antworten)) {
    all += usd
    count++
    if (bp === p) project += usd
    if (bc === chat) c = (c ?? 0) + usd
  }
  return { all, project, chat: c, count }
}

// Kosten der letzten Arbeit (Einblender, 15.10.2026): Antworten dieses Chats (samt Unteragenten) ab der eigenen Eingabe,
// aus demselben Buch wie «API:» in der Leiste; undefined, solange das Buch noch keine solche Antwort kennt
export function arbeitKosten(buch: Kostenbuch | undefined, chat: string, seit: number): number | undefined {
  if (!buch || !chat) return undefined
  let usd: number | undefined
  for (const [t, betrag, , bc] of Object.values(buch.antworten)) if (bc === chat && t >= seit) usd = (usd ?? 0) + betrag
  return usd
}

// Betrag wie «API:» in der Leiste: mit Tageskurs in Franken, ohne Kurs (offline) in Dollar, zwei Stellen, Komma
export function betragText(usd: number, usdChf: number | undefined): string {
  const kurs = typeof usdChf === 'number' && Number.isFinite(usdChf) && usdChf > 0 ? usdChf : undefined
  return `${(kurs === undefined ? usd : usd * kurs).toFixed(2).replace('.', ',')} ${kurs === undefined ? 'USD' : 'CHF'}`
}

// Beginn des laufenden Abo-Monats: derselbe Kalendertag wie beim Abschluss (z. B. der 14.), um dieselbe Uhrzeit
export function periodStart(subscribedAt: number, now: number): number {
  const s = new Date(subscribedAt)
  const n = new Date(now)
  const at = (y: number, mo: number) => {
    // kürzere Monate: auf den letzten Tag kürzen
    const last = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate()
    return Date.UTC(y, mo, Math.min(s.getUTCDate(), last), s.getUTCHours(), s.getUTCMinutes(), s.getUTCSeconds())
  }
  let start = at(n.getUTCFullYear(), n.getUTCMonth())
  if (start > now) start = at(n.getUTCFullYear(), n.getUTCMonth() - 1)
  return Math.max(start, subscribedAt)
}

files.hooks/aktion.ts:
// Aktionen von Anthropic (Cloud-Guthaben-Aktion, Gästepässe, Rabatt, Hinweise zum Nutzungslimit): Claude Code legt dazu in
// ~/.claude.json nur Merker ab. Aus ihnen wird ein Stand gebildet; weicht er vom bestätigten ab, zeigt die Leiste
// «⚑ Neue Aktion». Ein Klick darauf zeigt, was sich geändert hat, und bestätigt den Stand (Vorgabe 15.10.2026; vorher
// nur mit /aktion-gesehen). Beträge und Ablaufdaten von Guthaben liefert Claude Code nicht, darum zeigt die Leiste keine
// Guthaben mehr (Wahl Dominik 15.10.2026: «Cloud $» und «Gratis-Reset» veralteten, weil sie von Hand nachgeführt wurden).

// Stand in fester Form; als JSON ist er der Fingerabdruck. Gleiche Form wie bis 15.10.2026, nur die Zahl der Pässe zählt
// jetzt auch, wenn Claude Code sie als Zahl statt als Liste ablegt (seit 15.10.2026: «remaining_passes»: 3)
export type AktionStand = {
  promo: [string | null, boolean | null, boolean | null]
  passes: [boolean | null, number | null][]
  hinweise: number
  rabatt: number
}

// Zeilen höchstens so lang (das Kärtchen sitzt mitten in der STATUS-Zeile)
export const AKTION_ZEILE_MAX = 55

type Pass = { eligible?: boolean; remaining_passes?: unknown; limit?: unknown; referrer_reward?: { amount_minor_units?: unknown; currency?: unknown } }

function lesen(claudeJson: string): Record<string, unknown> | undefined {
  try {
    const j = JSON.parse(claudeJson)
    return j && typeof j === 'object' && !Array.isArray(j) ? (j as Record<string, unknown>) : undefined
  } catch {
    return undefined
  }
}
const objekt = (v: unknown): Record<string, unknown> => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : {})
const zahl = (v: unknown): number | undefined => (typeof v === 'number' && Number.isFinite(v) ? v : undefined)
const restPaesse = (v: unknown): number | null => (Array.isArray(v) ? v.length : (zahl(v) ?? null))
const paesse = (j: Record<string, unknown>) => Object.values(objekt(j.passesEligibilityCache)).map(p => objekt(p) as Pass)

export function aktionStand(claudeJson: string): AktionStand | undefined {
  const j = lesen(claudeJson)
  if (!j) return undefined
  const f = objekt(j.cachedGrowthBookFeatures)
  const promo = objekt(j.promoStartupStatusCache)
  const wahr = (v: unknown) => (typeof v === 'boolean' ? v : null)
  return {
    promo: [typeof promo.endpoint === 'string' ? promo.endpoint : null, wahr(promo.eligible), wahr(promo.claimed)],
    passes: paesse(j).map(p => [wahr(p.eligible), restPaesse(p.remaining_passes)]),
    hinweise: Array.isArray(f.tengu_rate_limit_promo_notices) ? f.tengu_rate_limit_promo_notices.length : 0,
    rabatt: zahl(objekt(f.tengu_penguin_mode_promo).discountPercent) ?? 0,
  }
}

export function aktionSignatur(claudeJson: string): string | undefined {
  const s = aktionStand(claudeJson)
  return s ? JSON.stringify(s) : undefined
}

function geld(minor: unknown, waehrung: unknown): string | undefined {
  const n = zahl(minor)
  if (n === undefined) return undefined
  const betrag = Number.isInteger(n / 100) ? String(n / 100) : (n / 100).toFixed(2).replace('.', ',')
  return `${betrag} ${waehrung === 'USD' || waehrung === undefined ? '$' : String(waehrung)}`
}

// Was sich gegenüber dem bestätigten Fingerabdruck geändert hat, in kurzen Zeilen mit dem heutigen Stand. Ohne lesbaren
// alten Stand: alles, was es gibt. Am Schluss, wo es Einzelheiten gibt.
export function aktionZeilen(claudeJson: string, bekannt: string | undefined): string[] {
  const j = lesen(claudeJson)
  const s = aktionStand(claudeJson)
  if (!j || !s) return []
  let alt: Partial<AktionStand> = {}
  try {
    alt = objekt(JSON.parse(bekannt ?? '')) as Partial<AktionStand>
  } catch {
    alt = {}
  }
  const anders = (a: unknown, b: unknown) => JSON.stringify(a) !== JSON.stringify(b)
  const zeilen: string[] = []
  if (anders(alt.promo, s.promo) && s.promo[0]) {
    const name = s.promo[0].split('/').pop() === 'cloud_credit' ? 'Cloud-Guthaben' : (s.promo[0].split('/').pop() ?? 'Aktion')
    const was = s.promo[2] ? 'eingelöst' : s.promo[1] ? 'verfügbar, noch nicht eingelöst' : 'nicht verfügbar'
    zeilen.push(`Aktion ${name}: ${was}`)
  }
  if (anders(alt.passes, s.passes)) {
    const liste = paesse(j)
    if (!liste.some(p => p.eligible === true)) zeilen.push('Gästepässe: keine')
    for (const p of liste.filter(x => x.eligible === true)) {
      const rest = restPaesse(p.remaining_passes)
      const limit = zahl(p.limit)
      const bonus = geld(p.referrer_reward?.amount_minor_units, p.referrer_reward?.currency)
      zeilen.push(`Gästepässe: ${rest ?? '?'}${limit !== undefined ? ` von ${limit}` : ''} frei${bonus ? `, Empfehlungsbonus ${bonus}` : ''}`)
    }
  }
  if (alt.hinweise !== s.hinweise) zeilen.push(s.hinweise > 0 ? `Hinweise zum Nutzungslimit: ${s.hinweise}` : 'Hinweise zum Nutzungslimit: keine mehr')
  if (alt.rabatt !== s.rabatt) {
    const ende = objekt(objekt(j.cachedGrowthBookFeatures).tengu_penguin_mode_promo).endDate
    zeilen.push(s.rabatt > 0 ? `Rabatt: ${s.rabatt} %${typeof ende === 'string' ? ` bis ${ende}` : ''}` : 'Rabatt: keiner mehr')
  }
  if (zeilen.length === 0) zeilen.push('Anthropic hat eine Aktion geändert')
  zeilen.push('Mehr: claude.ai › Einstellungen › Nutzung')
  return zeilen.map(z => (z.length > AKTION_ZEILE_MAX ? `${z.slice(0, AKTION_ZEILE_MAX - 1)}…` : z))
}

files.hooks/abgleich.ts:
// GitHub-Abgleich: Ein eigenes Abgleich-Skript (z. B. eine geplante Windows-Aufgabe) schreibt seinen Stand nach
// ~\.claude\github-abgleich.json. Die Leiste zeigt nur bei einer Störung «⚠ GitHub»; fehlt die Datei, nichts.

export const ABGLEICH_ALT_MS = 30 * 60 * 1000

// Liefert die Zeilen fürs Kärtchen, wenn etwas nicht stimmt; sonst undefined (dann bleibt die Leiste still)
export function abgleichWarnung(text: string, now: number): string[] | undefined {
  let s: { zeit?: string; letzterErfolg?: string | null; fehler?: unknown }
  try {
    s = JSON.parse(text.replace(/^\uFEFF/, ''))
  } catch {
    return ['Der GitHub-Abgleich hat noch keinen Stand geschrieben.', 'Abgleich-Skript prüfen.']
  }
  // «null» oder eine blosse Zahl ist gültiges JSON, aber kein Stand: wie «noch kein fehlerfreier Abgleich» (09.10.2026)
  if (typeof s !== 'object' || s === null) s = {}
  const fehler = Array.isArray(s.fehler) ? s.fehler.map(String) : []
  const erfolg = s.letzterErfolg ? Date.parse(s.letzterErfolg) : NaN
  const alt = !Number.isFinite(erfolg) || now - erfolg > ABGLEICH_ALT_MS
  if (fehler.length === 0 && !alt) return undefined
  const zeilen: string[] = [...fehler]
  if (alt) {
    zeilen.push(
      Number.isFinite(erfolg)
        ? `Letzter fehlerfreier Abgleich vor ${Math.round((now - erfolg) / 60000)} min.`
        : 'Noch kein fehlerfreier Abgleich.',
    )
    if (fehler.length === 0) zeilen.push('Abgleich-Skript prüfen.')
  }
  return zeilen
}

files.hooks/guthaben.ts:
// Guthaben mit Ablaufdatum (Cloud-Credits von Claude, Gratis-Reset usw.). Die Mod-Schnittstelle liefert diese
// Werte nicht, darum stehen sie in ~\.claude\statusleiste-guthaben.json (von Hand oder von Claude nachgeführt, Werte
// von claude.ai > Einstellungen > Nutzung). Die Leiste rechnet die Resttage selbst; fehlt die Datei, zeigt sie nichts.
// Der Fingerabdruck für «⚑ Neue Aktion» liegt in aktion.ts.

// kurz: Bezeichnung in der Leiste (z. B. «Cloud $»); fehlt sie, «Guthaben 1, 2 …» für Beträge, sonst der Name
// verbraucht: Gutschein schon eingelöst (z. B. Gratis-Reset benutzt) → nicht mehr zeigen
export type Guthaben = { name: string; kurz?: string; rest?: number; total?: number; einheit?: string; ablauf: string; verbraucht?: boolean }

// geld: ein Betrag (Cloud-Credits); sonst ein Gutschein ohne Betrag (z. B. Gratis-Reset)
export type GuthabenTeil = { name: string; kurz?: string; label: string; value: string; note: string; warn: boolean; geld: boolean }

// Ein Eintrag (aus der Datei oder dem State) in geprüfter Form: name und ablauf Pflicht, die übrigen Felder nur im
// richtigen Typ, sonst weggelassen. Eine Zahl in Anführungszeichen oder ein Objekt als kurz liess sonst das Zeichnen
// abstürzen, und die ganze Leiste fehlte (09.10.2026).
export function guthabenEintrag(g: unknown): Guthaben | undefined {
  if (typeof g !== 'object' || g === null) return undefined
  const e = g as Record<string, unknown>
  if (typeof e.name !== 'string' || typeof e.ablauf !== 'string' || !(Date.parse(e.ablauf) > 0)) return undefined
  const zahl = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : undefined)
  const out: Guthaben = { name: e.name, ablauf: e.ablauf }
  if (typeof e.kurz === 'string') out.kurz = e.kurz
  const rest = zahl(e.rest)
  if (rest !== undefined) out.rest = rest
  const total = zahl(e.total)
  if (total !== undefined) out.total = total
  if (typeof e.einheit === 'string') out.einheit = e.einheit
  if (typeof e.verbraucht === 'boolean') out.verbraucht = e.verbraucht
  return out
}

export function parseGuthaben(text: string): Guthaben[] {
  try {
    const list = JSON.parse(text)
    return Array.isArray(list) ? list.map(guthabenEintrag).filter((g): g is Guthaben => g !== undefined) : []
  } catch {
    return []
  }
}

// Versatz der Schweizer Zeit zu UTC: Sommerzeit vom letzten Sonntag im März bis zum letzten Sonntag im Oktober,
// je 01:00 UTC
export function swissOffsetMs(ms: number): number {
  const y = new Date(ms).getUTCFullYear()
  const lastSunday = (month: number) => {
    const last = new Date(Date.UTC(y, month + 1, 0, 1))
    return last.getTime() - last.getUTCDay() * 86400000
  }
  return ms >= lastSunday(2) && ms < lastSunday(9) ? 7200000 : 3600000
}

function betrag(v: number): string {
  // kein Zahlenwert (Datei von Hand gefüllt): «?» statt Absturz
  if (typeof v !== 'number' || !Number.isFinite(v)) return '?'
  return Number.isInteger(v) ? String(v) : v.toFixed(2).replace('.', ',')
}

// «Cloud-Guthaben: 248/250 $ bis 5.11. · noch 29 Tage»; abgelaufene, aufgebrauchte und eingelöste fallen weg; ab 7 Tagen vor Ablauf Warnung
export function guthabenTeile(list: readonly Guthaben[], now: number): GuthabenTeil[] {
  const out: GuthabenTeil[] = []
  for (const g of list) {
    const ablauf = Date.parse(g.ablauf)
    const ms = ablauf - now
    // Nur zeigen, was es wirklich gibt: abgelaufen, aufgebraucht (Betrag 0) oder eingelöst → weg
    if (!(ms > 0) || g.verbraucht === true || (g.rest !== undefined && g.rest <= 0)) continue
    const tage = Math.floor(ms / 86400000)
    // Datum in Schweizer Zeit, Sommer- und Winterzeit beachtet
    const d = new Date(ablauf + swissOffsetMs(ablauf))
    const datum = `${d.getUTCDate()}.${d.getUTCMonth() + 1}.`
    const menge =
      g.rest !== undefined ? `${betrag(g.rest)}${g.total !== undefined ? `/${betrag(g.total)}` : ''} ${g.einheit ?? ''}`.trim() + ' ' : ''
    out.push({
      name: g.name,
      ...(g.kurz ? { kurz: g.kurz } : {}),
      geld: g.rest !== undefined,
      label: `${g.name}:`,
      value: `${menge}bis ${datum}`,
      note: tage >= 1 ? `noch ${tage} Tag${tage === 1 ? '' : 'e'}` : `noch ${Math.max(1, Math.round(ms / 3600000))} h`,
      warn: tage < 7,
    })
  }
  return out
}

